export function resolveDetailPage(locale: Locale, slug: string) {
  const entry = (Object.keys(detailContent) as DetailRouteKey[]).find((key) => localizedRoutes[key][locale].endsWith(`/${slug}`));
  return entry ? { routeKey: entry, page: detailContent[entry][locale] } : null;
}
